NSString*OR6ChatCodexError(NSError*e){if(!e)return nil;if(e.userInfo[@"oauthFailure"])return OR6ChatCodexPairAuthorizationFailureText(e.userInfo[@"oauthFailure"]);NSString*c=e.userInfo[@"code"];if([c isEqual:@"expired"])return OR6L(@"Request is no longer active.");if([c isEqual:@"stale_context"])return OR6L(@"The Codex connection changed. Open it again.");if([e.userInfo[@"dispatch"]isEqual:@"possible"])return OR6L(@"The result is unconfirmed. Read the task history before sending again.");if([c isEqual:@"rate_limited"])return OR6L(@"The service asked us to wait. No action was repeated.");if([c isEqual:@"service_challenge"]||[c isEqual:@"not_authenticated"])return OR6L(@"Codex could not verify this session. Check Account before connecting again.");if([c isEqual:@"invalid_request"]||[c isEqual:@"schema_mismatch"])return OR6L(@"Codex could not accept this request. Check the values and the connection.");return OR6L(@"Codex is unavailable. Your draft is kept.");}
@interface OR6CodexAlert:NSObject<UIAlertViewDelegate>{void(^_done)(NSString*);BOOL _input;}
