@end
@implementation OR6CodexAlert
- (id)initTitle:(NSString*)title message:(NSString*)message action:(NSString*)action input:(BOOL)input done:(void(^)(NSString*))done{if((self=[super init])){_done=[done copy];_input=input;UIAlertView*a=[[[UIAlertView alloc]initWithTitle:title message:message delegate:self cancelButtonTitle:OR6L(@"Cancel")otherButtonTitles:action,nil]autorelease];if(input)a.alertViewStyle=UIAlertViewStylePlainTextInput;[a show];}return self;}
- (void)alertView:(UIAlertView*)a clickedButtonAtIndex:(NSInteger)i{if(i!=a.cancelButtonIndex&&_done)_done(_input?[a textFieldAtIndex:0].text:@"");[self autorelease];}
- (void)dealloc{[_done release];[super dealloc];}
@end
void OR6ChatCodexAlert(NSString*t,NSString*m,NSString*a,BOOL input,void(^done)(NSString*)){(void)[[OR6CodexAlert alloc]initTitle:t message:m action:a input:input done:done];}

