 OR6ChatCodexModel*_model;NSString*_page;NSMutableDictionary*_parameters,*_fields;NSMutableArray*_items;void(^_done)(NSDictionary*);BOOL _loaded;NSString*_cursor,*_scope;OR6ChatCodexImages*_images;
