@interface OR6CodexModels:RCChecklistViewController<RCChecklistDelegate>{OR6ChatCodexModel*_model;NSString*_thread,*_modelID,*_effort,*_tier,*_cursor;NSMutableArray*_models;void(^_done)(NSDictionary*);}
