@implementation OR6CodexModels
- (id)initBackend:(id<OR6ChatCodexBackend>)b parameters:(NSDictionary*)p done:(void(^)(NSDictionary*))done{if((self=[super init])){self.title=OR6L(@"Model");self.delegate=self;_model=[[OR6ChatCodexModel alloc]initWithBackend:b];_thread=[p[@"threadId"]copy];_modelID=[p[@"model"]copy];_effort=[p[@"effort"]copy];_models=[NSMutableArray new];_done=[done copy];}return self;}
- (void)viewDidLoad{[super viewDidLoad];self.tableView.accessibilityIdentifier=@"chat.codex.models";self.navigationItem.rightBarButtonItem=[[[UIBarButtonItem alloc]initWithTitle:OR6L(@"Done")style:UIBarButtonItemStyleDone target:self action:@selector(save)]autorelease];[self loadMore];}
- (void)loadMore{self.busy=YES;NSMutableDictionary*p=[NSMutableDictionary dictionaryWithObject:@50 forKey:@"limit"];if(_cursor)p[@"cursor"]=_cursor;[_model call:@"codex.models.list"parameters:p slot:@"models"mutation:NO completion:^(NSDictionary*r,NSError*e){self.busy=NO;if(!e){if(_models.count+[r[@"data"]count]<=256)[_models addObjectsFromArray:r[@"data"]];[_cursor release];_cursor=r[@"nextCursor"]!=NSNull.null?[r[@"nextCursor"]copy]:nil;}[self render];}];}
- (NSDictionary*)selected{for(NSDictionary*m in _models)if([m[@"model"]isEqual:_modelID])return m;return nil;}
- (void)render{NSMutableArray*a=[NSMutableArray array],*efforts=[NSMutableArray array],*tiers=[NSMutableArray array];for(NSDictionary*m in _models){RCChecklistRow*r=[RCChecklistRow rowWithTitle:T(m[@"displayName"])detail:T(m[@"description"])checked:[m[@"model"]isEqual:_modelID]];r.identifier=@"chat.codex.model";[a addObject:r];}if(_cursor)[a addObject:[RCChecklistRow rowWithTitle:OR6L(@"Show more")detail:nil checked:NO]];NSDictionary*m=[self selected];for(NSDictionary*e in m[@"supportedReasoningEfforts"])[efforts addObject:[RCChecklistRow rowWithTitle:T(e[@"reasoningEffort"])detail:T(e[@"description"])checked:[e[@"reasoningEffort"]isEqual:_effort]]];[tiers addObject:[RCChecklistRow rowWithTitle:OR6L(@"Standard")detail:nil checked:!_tier]];for(NSDictionary*t in m[@"serviceTiers"])[tiers addObject:[RCChecklistRow rowWithTitle:T(t[@"name"])detail:T(t[@"description"])checked:[t[@"id"]isEqual:_tier]]];self.sections=@[[RCChecklistSection sectionWithTitle:OR6L(@"Model")rows:a],[RCChecklistSection sectionWithTitle:OR6L(@"Reasoning depth")rows:efforts],[RCChecklistSection sectionWithTitle:OR6L(@"Speed")rows:tiers]];self.footerText=_model.error?OR6ChatCodexError(_model.error):OR6L(@"The list comes from the account; models it does not offer are not shown.");}
- (void)checklist:(RCChecklistViewController*)c didSelectRow:(NSUInteger)i inSection:(NSUInteger)s{(void)c;if(s==0){if(i==_models.count){[self loadMore];return;}NSDictionary*m=_models[i];[_modelID release];_modelID=[m[@"model"]copy];[_effort release];_effort=[m[@"defaultReasoningEffort"]copy];[_tier release];_tier=nil;}else if(s==1){[_effort release];_effort=[[self selected][@"supportedReasoningEfforts"][i][@"reasoningEffort"]copy];}else{[_tier release];_tier=i?[[self selected][@"serviceTiers"][i-1][@"id"]copy]:nil;}[self render];}
- (void)save{if(!_modelID||!_effort||_model.stale)return;NSMutableDictionary*p=[NSMutableDictionary dictionaryWithDictionary:@{@"model":_modelID,@"effort":_effort}];p[@"serviceTier"]=_tier?:NSNull.null;if(!_thread){if(_done)_done(p);[self.navigationController popViewControllerAnimated:YES];return;}p[@"threadId"]=_thread;self.busy=YES;[_model call:@"codex.model.set"parameters:p slot:@"saved"mutation:YES completion:^(NSDictionary*r,NSError*e){self.busy=NO;if(e){[self render];return;}if(_done)_done(p);[RCHUD showText:[r[@"confirmed"]isEqual:@YES]?OR6L(@"Saved"):OR6L(@"Sent · waiting for confirmation")kind:RCHUDTextOnly inView:self.view.window seconds:2];[self.navigationController popViewControllerAnimated:YES];}];}
- (void)dealloc{self.delegate=nil;[_model cancel];[_model release];[_thread release];[_modelID release];[_effort release];[_tier release];[_cursor release];[_models release];[_done release];[super dealloc];}
@end

@implementation OR6CodexForm
- (id)initBackend:(id<OR6ChatCodexBackend>)b page:(NSString*)page parameters:(NSDictionary*)p done:(void(^)(NSDictionary*))done{if((self=[super init])){_model=[[OR6ChatCodexModel alloc]initWithBackend:b];_page=[page copy];_parameters=[(p?:@{})mutableCopy];_fields=[NSMutableDictionary new];_items=[NSMutableArray new];_done=[done copy];if([page isEqual:@"new"]){_images=[[OR6ChatCodexImages alloc]initWithBackend:b owner:self];_images.delegate=self;}self.delegate=self;[NSNotificationCenter.defaultCenter addObserver:self selector:@selector(changed:)name:OR6ChatCodexModelChanged object:_model];}return self;}
- (void)viewDidLoad{[super viewDidLoad];self.tableView.accessibilityIdentifier=[@"chat.codex."stringByAppendingString:_page];}
- (void)viewWillAppear:(BOOL)a{[super viewWillAppear:a];if(([_page isEqual:@"home"]||[_page isEqual:@"new"]||[_page isEqual:@"connections"])&&_model.stale){if(![_model sameAccount])[_fields removeAllObjects];[_items removeAllObjects];[_cursor release];_cursor=nil;[_model rebind];_loaded=NO;}else if(([_page isEqual:@"connections"]||[_page isEqual:@"new"])&&_loaded){[self read:@"ui.connections.list"params:@{}slot:@"connections"];if([_page isEqual:@"new"])[self read:@"ui.environment.get"params:@{}slot:@"environment"];}if(!_loaded){_loaded=YES;[self loadPage];}[self render];}
- (void)viewWillDisappear:(BOOL)a{[super viewWillDisappear:a];if(self.isMovingFromParentViewController)[_model cancel];}
- (void)changed:(NSNotification*)n{(void)n;if(self.isViewLoaded)[self render];}
- (RCFormRow*)row:(NSString*)title value:(NSString*)value action:(id)action key:(NSString*)key{RCFormRow*r=[RCFormRow rowWithKind:RCFormRowValue title:title];r.value=value;r.userInfo=action;r.identifier=[@"chat.codex."stringByAppendingString:key];r.disclosure=action!=nil;return r;}
- (RCFormRow*)button:(NSString*)title action:(id)action key:(NSString*)key{RCFormRow*r=[self row:title value:nil action:action key:key];r.kind=RCFormRowButton;return r;}
- (RCFormRow*)note:(NSString*)text{RCFormRow*r=[RCFormRow rowWithKind:RCFormRowNote title:text];return r;}
- (RCFormRow*)field:(NSString*)title key:(NSString*)key multiline:(BOOL)longer{RCFormRow*r=[RCFormRow rowWithKind:longer?RCFormRowLongText:RCFormRowText title:title];r.text=T(_fields[key]);r.placeholder=title;r.maxLength=longer?16000:4096;r.identifier=[@"chat.codex.field."stringByAppendingString:key];r.userInfo=@{@"field":key};return r;}
- (void)read:(NSString*)op params:(NSDictionary*)p slot:(NSString*)slot{[_model call:op parameters:p slot:slot mutation:NO completion:nil];}
- (void)push:(NSString*)page p:(NSDictionary*)p done:(void(^)(NSDictionary*))done{[self.navigationController pushViewController:OR6ChatCodexForm(_model.backend,page,p,done)animated:YES];}
- (void)loadPage{
 if([_page isEqual:@"home"]){self.title=OR6L(@"Codex");[self read:@"ui.connections.list"params:@{}slot:@"connections"];if(_model.data[@"connections"][@"selected"]&&_model.data[@"connections"][@"selected"]!=NSNull.null){[self read:@"codex.home.get"params:@{}slot:@"status"];if([_model.data[@"status"][@"state"]isEqual:@"ready"])[self tasks:NO];}}
 else if([_page isEqual:@"connections"]){self.title=OR6L(@"Connections");[self read:@"ui.connections.list"params:@{}slot:@"connections"];}
 else if([_page isEqual:@"ssh"]){self.title=OR6L(@"Manually over SSH");_fields[@"port"]=@"22";}
 else if([_page isEqual:@"new"]){self.title=OR6L(@"New task");[self read:@"codex.home.get"params:@{}slot:@"seven"];[self read:@"ui.environment.get"params:@{}slot:@"environment"];[self read:@"ui.connections.list"params:@{}slot:@"connections"];self.navigationItem.rightBarButtonItem=[[[UIBarButtonItem alloc]initWithTitle:OR6L(@"Send")style:UIBarButtonItemStyleDone target:self action:@selector(createTask)]autorelease];}
 else if([_page isEqual:@"workspace"]){self.title=T(_parameters[@"path"]);[self read:@"codex.workspace.list"params:@{@"path":_parameters[@"path"]?:@"/"}slot:@"folders"];}
 else if([_page isEqual:@"mcp"]){self.title=OR6L(@"Tools");[self read:@"codex.mcp.servers"params:@{@"threadId":_parameters[@"threadId"]}slot:@"mcp"];}
 else if([_page isEqual:@"server"]){self.title=T(_parameters[@"server"][@"name"]);}
 else if([_page isEqual:@"terminals"]){self.title=OR6L(@"Commands");[self read:@"codex.commands.list"params:@{@"threadId":_parameters[@"threadId"]}slot:@"terminals"];}
 else if([_page isEqual:@"recovery"]){self.title=OR6L(@"Recovery");[self read:@"codex.recovery.journal"params:@{}slot:@"journal"];}
 else if([_page isEqual:@"plan"]){self.title=OR6L(@"Work plan");[self read:@"codex.plan.modes"params:@{}slot:@"modes"];}
 else if([_page isEqual:@"comment"]){self.title=OR6L(@"Review comment");_fields[@"path"]=_parameters[@"path"]?:@"";_fields[@"line"]=@"1";}
 else if([_page isEqual:@"form"]){self.title=T(_parameters[@"request"][@"params"][@"serverName"]);}
 else if([_page isEqual:@"resource"]){self.title=OR6L(@"Resource");[self read:@"codex.mcp.resource"params:_parameters slot:@"resource"];}
}
- (void)tasks:(BOOL)more{NSMutableDictionary*p=[NSMutableDictionary dictionaryWithDictionary:@{@"limit":@30,@"sortKey":_fields[@"sort"]?:@"updated_at",@"sortDirection":@"desc"}];for(NSString*k in @[@"cwd",@"projectId",@"searchTerm"])if([_fields[k]length])p[k]=_fields[k];if(more&&_cursor)p[@"cursor"]=_cursor;[_model call:@"codex.tasks.list"parameters:p slot:@"tasks"mutation:NO completion:^(NSDictionary*r,NSError*e){if(e)return;if(!more)[_items removeAllObjects];if(_items.count+[r[@"data"]count]<=256)[_items addObjectsFromArray:r[@"data"]];[_cursor release];_cursor=r[@"nextCursor"]&&r[@"nextCursor"]!=NSNull.null?[r[@"nextCursor"]copy]:nil;}];}
- (void)cloudPage:(NSString*)scope cursor:(NSString*)cursor{NSMutableDictionary*p=[NSMutableDictionary dictionaryWithObject:scope forKey:@"scope"];if(cursor)p[@"cursor"]=cursor;[_model call:@"codex.cloud.environments.list"parameters:p slot:scope mutation:NO completion:^(NSDictionary*r,NSError*e){(void)r;if(e)return;}];}
- (void)render{
 if(!self.isViewLoaded)return;self.busy=_model.busy||_images.busy;NSMutableArray*sections=[NSMutableArray array],*rows=[NSMutableArray array];NSDictionary*d=_model.data;
 if(_model.error)[rows addObject:[self note:OR6ChatCodexError(_model.error)]];if(_model.uncertain)[rows addObject:[self button:OR6L(@"Recovery")action:@"recovery"key:@"uncertain.recovery"]];
 if(_model.stale){self.sections=@[[RCFormSection sectionWithTitle:nil rows:rows]];return;}
 if([_page isEqual:@"home"]){
  NSDictionary*s=d[@"status"];BOOL ready=[s[@"state"]isEqual:@"ready"],selected=d[@"connections"][@"selected"]&&d[@"connections"][@"selected"]!=NSNull.null;
  BOOL cloud=[d[@"connections"][@"cloud"]boolValue];NSString*host=nil;for(NSDictionary*p in d[@"connections"][@"data"])if([p[@"selected"]boolValue])host=T(p[@"name"]);
  RCFormRow*where=[self row:cloud?OR6L(@"Cloud"):host.length?host:OR6L(@"No computer selected")value:nil action:@"connections"key:@"connections"];where.glyph=cloud?@"cloud":@"devices";where.tile=cloud?RCTileBlue:RCTileDark;
  if(cloud||selected){where.showsLamp=YES;where.lamp=cloud||ready?RCLampOK:RCLampOff;where.subtitle=cloud||ready?OR6L(@"Connected"):OR6L(@"Not connected");}else where.subtitle=OR6L(@"Choose a computer or the cloud");[rows addObject:where];
  if(selected&&!cloud)[rows addObject:[self button:ready?OR6L(@"Disconnect"):OR6L(@"Connect")action:ready?@"disconnect":@"connect"key:@"connect"]];else if(!cloud)[rows addObject:[self button:OR6L(@"Add a computer…")action:@"add-computer"key:@"connection.add"]];
  RCFormSection*top=[RCFormSection sectionWithTitle:nil rows:rows];if(!ready&&!cloud)top.footer=OR6L(@"Codex runs tasks on your computer or in the cloud. This iPhone shows the progress and asks you only when a decision is needed.");[sections addObject:top];rows=[NSMutableArray array];
  if(ready){for(NSDictionary*t in _items){RCFormRow*r=[self row:[T(t[@"name"])length]?t[@"name"]:[T(t[@"preview"])length]?t[@"preview"]:OR6L(@"Untitled")value:nil action:@{@"task":t}key:@"task"];r.subtitle=T(t[@"cwd"]);r.showsLamp=YES;r.lamp=[t[@"status"][@"type"]isEqual:@"active"]?RCLampBusy:RCLampOff;[rows addObject:r];}if(!_items.count)[rows addObject:[self note:OR6L(@"No Codex tasks yet.")]];if(_cursor)[rows addObject:[self button:OR6L(@"Show more")action:@"more"key:@"more"]];[rows addObject:[self button:OR6L(@"New task")action:@"new"key:@"new"]];[sections addObject:[RCFormSection sectionWithTitle:OR6L(@"Tasks")rows:rows]];rows=[NSMutableArray arrayWithArray:@[[self field:OR6L(@"Search")key:@"searchTerm"multiline:NO],[self field:OR6L(@"Project folder")key:@"cwd"multiline:NO],[self field:OR6L(@"Project")key:@"projectId"multiline:NO],[self row:OR6L(@"Sort")value:[_fields[@"sort"]isEqual:@"created_at"]?OR6L(@"Created"):OR6L(@"Updated")action:@"sort"key:@"sort"],[self button:OR6L(@"Search")action:@"search"key:@"search"]]];[sections addObject:[RCFormSection sectionWithTitle:OR6L(@"Search")rows:rows]];}
  self.sections=sections;return;
 }
 if([_page isEqual:@"connections"]){for(NSDictionary*p in d[@"connections"][@"data"]){RCFormRow*r=[self row:T(p[@"name"])value:[p[@"selected"]boolValue]?OR6L(@"in use"):nil action:@{@"profile":p}key:@"connection"];r.subtitle=[p[@"type"]isEqual:@"relay"]?OR6L(@"Paired computer"):[NSString stringWithFormat:@"%@ · %@:%@",T(p[@"username"]),T(p[@"host"]),p[@"port"]];r.glyph=@"devices";r.tile=RCTileDark;r.showsLamp=YES;r.lamp=[p[@"state"]isEqual:@"online"]?RCLampOK:[p[@"state"]isEqual:@"connecting"]?RCLampBusy:RCLampOff;[rows addObject:r];}[rows addObject:[self button:OR6L(@"Add a computer…")action:@"add-computer"key:@"connection.add"]];[sections addObject:[RCFormSection sectionWithTitle:OR6L(@"Computers")rows:rows]];rows=[NSMutableArray arrayWithObject:[self button:OR6L(@"Cloud environments")action:@"cloud"key:@"cloud"]];for(NSString*scope in @[@"user",@"workspace"]){for(NSDictionary*e in d[scope][@"data"]){RCFormRow*r=[self row:T(e[@"name"])value:nil action:@{@"environment":e}key:@"environment"];r.subtitle=T(e[@"description"]);r.glyph=@"cloud";r.tile=RCTileBlue;[rows addObject:r];}id next=d[scope][@"nextCursor"];if(next&&next!=NSNull.null)[rows addObject:[self button:OR6L(@"Show more")action:@{@"scope":scope,@"cursor":next}key:@"environment.more"]];}[sections addObject:[RCFormSection sectionWithTitle:OR6L(@"Cloud")rows:rows]];self.sections=sections;return;}
 if([_page isEqual:@"ssh"]){[rows addObjectsFromArray:@[[self field:OR6L(@"Computer")key:@"name"multiline:NO],[self field:OR6L(@"Host")key:@"host"multiline:NO],[self field:OR6L(@"Port")key:@"port"multiline:NO],[self field:OR6L(@"Login")key:@"username"multiline:NO]]];[sections addObject:[RCFormSection sectionWithTitle:OR6L(@"Computer")rows:rows]];rows=[NSMutableArray array];if(d[@"key"][@"publicKey"])[rows addObject:[self note:d[@"key"][@"publicKey"]]];[rows addObject:[self button:OR6L(@"Copy public key")action:@"key"key:@"ssh.copy"]];[rows addObject:[self button:OR6L(@"Connect")action:@"probe"key:@"ssh.connect"]];RCFormSection*s=[RCFormSection sectionWithTitle:OR6L(@"iPhone key")rows:rows];s.footer=OR6L(@"Add the public key to ~/.ssh/authorized_keys on the computer. The private key never leaves this iPhone.");[sections addObject:s];self.sections=sections;return;}
 if([_page isEqual:@"new"]){[rows addObjectsFromArray:@[[self field:OR6L(@"Task")key:@"text"multiline:YES],[self row:OR6L(@"Where to run")value:T(d[@"environment"][@"environment"][@"name"])action:@"connections"key:@"where"]]];if(![d[@"connections"][@"cloud"]boolValue]){[rows addObject:[self field:OR6L(@"Project folder")key:@"cwd"multiline:NO]];[rows addObject:[self button:OR6L(@"Choose folder…")action:@"workspace"key:@"workspace"]];if(OR6ChatCodexSevenAvailable(d[@"seven"])){[rows addObject:[self row:OR6L(@"Working tree")value:OR6L(@"Current branch")action:@"worktrees"key:@"worktrees"]];[rows addObject:[self row:OR6L(@"Goal and budget")value:T(_fields[@"goal"]).length?_fields[@"goal"]:OR6L(@"No goal")action:@"new-goal"key:@"new.goal"]];for(NSUInteger i=0;i<_images.tokens.count;i++){RCFormRow*r=[self row:OR6L(@"Image")value:OR6L(@"Ready to send")action:@{@"image":@(i)}key:@"new.image"];r.glyph=@"photo";r.tile=RCTileBlue;[rows addObject:r];}if(_images.tokens.count<2)[rows addObject:[self button:OR6L(@"Add screenshot")action:@"new-image"key:@"new.image.add"]];if(_images.note)[rows addObject:[self note:_images.note]];}}}
 else if([_page isEqual:@"workspace"]){[rows addObject:[self button:OR6L(@"Use this folder")action:@"choose-folder"key:@"folder.choose"]];[rows addObject:[self button:OR6L(@"New folder…")action:@"mkdir"key:@"folder.create"]];for(NSDictionary*f in d[@"folders"][@"entries"])if([f[@"isDirectory"]boolValue]){RCFormRow*r=[self row:T(f[@"fileName"])value:nil action:@{@"folder":f[@"fileName"]}key:@"folder"];r.glyph=@"folder";r.tile=RCTileBlue;[rows addObject:r];}}
 else if([_page isEqual:@"recovery"]){NSDictionary*records=d[@"journal"][@"records"];for(NSString*k in[[records allKeys]sortedArrayUsingSelector:@selector(compare:)]){NSDictionary*r=records[k];RCFormRow*row=[self row:T(r[@"method"])value:T(r[@"state"])action:r[@"threadId"]?@{@"task":@{@"id":r[@"threadId"]}}:nil key:@"recovery.record"];row.subtitle=T(r[@"threadId"]);[rows addObject:row];}if(!records.count)[rows addObject:[self note:OR6L(@"No pending operations.")]];}
 else if([_page isEqual:@"terminals"]){for(NSDictionary*t in d[@"terminals"][@"data"]){RCFormRow*r=[self row:T(t[@"command"])value:OR6L(@"Stop")action:@{@"terminal":t}key:@"terminal.stop"];r.subtitle=T(t[@"cwd"]);[rows addObject:r];}if(![d[@"terminals"][@"data"]count])[rows addObject:[self note:OR6L(@"No running commands.")]];}
 else if([_page isEqual:@"mcp"]){for(NSDictionary*s in d[@"mcp"][@"data"])[rows addObject:[self row:T(s[@"name"])value:T(s[@"authStatus"])action:@{@"server":s}key:@"mcp.server"]];id n=d[@"mcp"][@"nextCursor"];if(n&&n!=NSNull.null)[rows addObject:[self button:OR6L(@"Show more")action:@{@"mcpCursor":n}key:@"mcp.more"]];}
 else if([_page isEqual:@"server"]){NSDictionary*s=_parameters[@"server"];for(NSDictionary*r in s[@"resources"])[rows addObject:[self row:T(r[@"name"])value:nil action:@{@"resource":r[@"uri"]}key:@"mcp.resource"]];for(NSString*k in s[@"tools"]){NSDictionary*t=s[@"tools"][k];[rows addObject:[self note:[NSString stringWithFormat:@"%@\n%@",k,T(t[@"description"])]]];}}
