 else if([_page isEqual:@"plan"]){[rows addObject:[self field:OR6L(@"What should Codex plan?")key:@"text"multiline:YES]];[rows addObject:[self button:OR6L(@"Model")action:@"model-for-plan"key:@"plan.model"]];if(_fields[@"model"]&&_fields[@"effort"])[rows addObject:[self button:OR6L(@"Plan")action:@"plan-start"key:@"plan.start"]];}
 else if([_page isEqual:@"comment"]){[rows addObjectsFromArray:@[[self field:OR6L(@"File")key:@"path"multiline:NO],[self field:OR6L(@"Line")key:@"line"multiline:NO],[self row:OR6L(@"Side")value:[_fields[@"side"]isEqual:@"old"]?OR6L(@"Before"):OR6L(@"After")action:@"comment-side"key:@"comment.side"],[self field:OR6L(@"Comment")key:@"text"multiline:YES],[self button:OR6L(@"Send")action:@"comment-send"key:@"review.comment"]]];}
 else if([_page isEqual:@"form"]){NSDictionary*q=_parameters[@"request"][@"params"],*props=q[@"requestedSchema"][@"properties"];[rows addObject:[self note:T(q[@"message"])]];for(NSString*k in[[props allKeys]sortedArrayUsingSelector:@selector(compare:)]){NSDictionary*s=props[k];RCFormRow*r=[self field:[T(s[@"title"])length]?s[@"title"]:k key:k multiline:[s[@"type"]isEqual:@"array"]];if([s[@"type"]isEqual:@"boolean"]){r.kind=RCFormRowSwitch;r.on=[_fields[k]boolValue];if(!_fields[k])_fields[k]=@NO;}if([s[@"enum"]isKindOfClass:NSArray.class]){r.kind=RCFormRowValue;r.value=[_fields[k]description];r.disclosure=YES;r.userInfo=@{@"fieldChoice":k};}if([s[@"type"]isEqual:@"array"]&&[s[@"items"][@"enum"]isKindOfClass:NSArray.class]){NSArray*values=s[@"items"][@"enum"];for(NSUInteger i=0;i<values.count;i++){RCFormRow*choice=[RCFormRow rowWithKind:RCFormRowCheck title:[values[i]description]];choice.checked=[_fields[k]containsObject:values[i]];choice.identifier=@"chat.codex.mcp.choice";choice.userInfo=@{@"toggleEnum":k,@"index":@(i)};[rows addObject:choice];}continue;}r.subtitle=T(s[@"description"]);[rows addObject:r];}[rows addObject:[self button:OR6L(@"Allow")action:@"form-send"key:@"mcp.form.send"]];}
